window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-349057b0dcc4fdf2"]={"versions": [{"id": "FIG-349057b0dcc4fdf2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Health Managements (PHM). Das Diagramm definiert die Vererbungshierarchie von Schnittstellen für Recovery-Benachrichtigungen ausgehend von der allgemeinen M2-Metaklasse <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basismetasklasse mit den Stereotypen bzw. Typisierungen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Spezialisiert als abstrakte Klasse direkt <code>PortInterface</code>.\n</li><li><code>PhmAbstractRecoveryNotificationInterface</code>: Spezialisiert als abstrakte Klasse <code>PlatformHealthManagementInterface</code>.\n</li><li><code>PhmSupervisionRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Überwachungs-Recovery-Benachrichtigungen.\n</li><li><code>PhmHealthChannelRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Recovery-Benachrichtigungen bezüglich Health-Channels.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen repräsentieren Generalisierungen/Spezialisierungen (<code>is-a</code>) zur typisierten Benachrichtigung von Wiederherstellungsaktionen im PHM-Kontext.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Festlegung der Vererbungsstruktur für PHM-Recovery-Notification-Schnittstellen im Manifest. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass Recovery-Notifikationsports entweder als <code>PhmSupervisionRecoveryNotificationInterface</code> oder <code>PhmHealthChannelRecoveryNotificationInterface</code> instanziiert werden und die Eigenschaften von <code>ARElement</code> bzw. <code>PortInterface</code> erben.</p>"}, {"id": "FIG-61f470539b21a6d1", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Health Managements (PHM). Das Diagramm definiert die Vererbungshierarchie von Schnittstellen für Recovery-Benachrichtigungen ausgehend von der allgemeinen M2-Metaklasse <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basismetasklasse mit den Stereotypen bzw. Typisierungen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Spezialisiert als abstrakte Klasse direkt <code>PortInterface</code>.\n</li><li><code>PhmAbstractRecoveryNotificationInterface</code>: Spezialisiert als abstrakte Klasse <code>PlatformHealthManagementInterface</code>.\n</li><li><code>PhmSupervisionRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Überwachungs-Recovery-Benachrichtigungen.\n</li><li><code>PhmHealthChannelRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Recovery-Benachrichtigungen bezüglich Health-Channels.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen repräsentieren Generalisierungen/Spezialisierungen (<code>is-a</code>) zur typisierten Benachrichtigung von Wiederherstellungsaktionen im PHM-Kontext.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Festlegung der Vererbungsstruktur für PHM-Recovery-Notification-Schnittstellen im Manifest. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass Recovery-Notifikationsports entweder als <code>PhmSupervisionRecoveryNotificationInterface</code> oder <code>PhmHealthChannelRecoveryNotificationInterface</code> instanziiert werden und die Eigenschaften von <code>ARElement</code> bzw. <code>PortInterface</code> erben.</p>"}, {"id": "FIG-23b47d9b1e98cc46", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Health Managements (PHM). Das Diagramm definiert die Vererbungshierarchie von Schnittstellen für Recovery-Benachrichtigungen ausgehend von der allgemeinen M2-Metaklasse <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basismetasklasse mit den Stereotypen bzw. Typisierungen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Spezialisiert als abstrakte Klasse direkt <code>PortInterface</code>.\n</li><li><code>PhmAbstractRecoveryNotificationInterface</code>: Spezialisiert als abstrakte Klasse <code>PlatformHealthManagementInterface</code>.\n</li><li><code>PhmSupervisionRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Überwachungs-Recovery-Benachrichtigungen.\n</li><li><code>PhmHealthChannelRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Recovery-Benachrichtigungen bezüglich Health-Channels.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen repräsentieren Generalisierungen/Spezialisierungen (<code>is-a</code>) zur typisierten Benachrichtigung von Wiederherstellungsaktionen im PHM-Kontext.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Festlegung der Vererbungsstruktur für PHM-Recovery-Notification-Schnittstellen im Manifest. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass Recovery-Notifikationsports entweder als <code>PhmSupervisionRecoveryNotificationInterface</code> oder <code>PhmHealthChannelRecoveryNotificationInterface</code> instanziiert werden und die Eigenschaften von <code>ARElement</code> bzw. <code>PortInterface</code> erben.</p>"}, {"id": "FIG-97e305141de0f277", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Health Managements (PHM). Das Diagramm definiert die Vererbungshierarchie von Schnittstellen für Recovery-Benachrichtigungen ausgehend von der allgemeinen M2-Metaklasse <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Modellelemente und Generalisierungsbeziehungen:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Abstrakte Basismetasklasse mit den Stereotypen bzw. Typisierungen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code> und <code>AtpType</code>.\n</li><li><code>PlatformHealthManagementInterface</code>: Spezialisiert als abstrakte Klasse direkt <code>PortInterface</code>.\n</li><li><code>PhmAbstractRecoveryNotificationInterface</code>: Spezialisiert als abstrakte Klasse <code>PlatformHealthManagementInterface</code>.\n</li><li><code>PhmSupervisionRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Überwachungs-Recovery-Benachrichtigungen.\n</li><li><code>PhmHealthChannelRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> für Recovery-Benachrichtigungen bezüglich Health-Channels.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen repräsentieren Generalisierungen/Spezialisierungen (<code>is-a</code>) zur typisierten Benachrichtigung von Wiederherstellungsaktionen im PHM-Kontext.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Festlegung der Vererbungsstruktur für PHM-Recovery-Notification-Schnittstellen im Manifest. Modellierer und Validierungswerkzeuge müssen sicherstellen, dass Recovery-Notifikationsports entweder als <code>PhmSupervisionRecoveryNotificationInterface</code> oder <code>PhmHealthChannelRecoveryNotificationInterface</code> instanziiert werden und die Eigenschaften von <code>ARElement</code> bzw. <code>PortInterface</code> erben.</p>"}, {"id": "FIG-e1886a37b828dc9f", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Health Managements (PHM). Das Diagramm modelliert die Vererbungshierarchie der Recovery-Benachrichtigungsschnittstellen ausgehend von der Metaklasse <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst eine lineare Generalisierungshierarchie:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basismetasklasse ohne gesondert dargestellte Stereotypen.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmAbstractRecoveryNotificationInterface</code>: Abstrakte Spezialisierung von <code>PlatformHealthManagementInterface</code>.\n</li><li><code>PhmSupervisionRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen repräsentieren Generalisierungen/Spezialisierungen (<code>is-a</code>) zur typisierten Benachrichtigung von Wiederherstellungsaktionen im PHM-Kontext.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Festlegung der Metamodellstruktur für Benachrichtigungsschnittstellen im PHM. Für Recovery-Benachrichtigungen steht im gezeigten Metamodell als Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> die Schnittstelle <code>PhmSupervisionRecoveryNotificationInterface</code> zur Verfügung. Validierungswerkzeuge und Codegeneratoren müssen Manifeste auf diese Schnittstellenhierarchie abstimmen.</p>"}, {"id": "FIG-ab21472678ff724e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR Adaptive Platform Health Managements (PHM). Das Diagramm modelliert die Vererbungshierarchie der Recovery-Benachrichtigungsschnittstellen ausgehend von der Metaklasse <code>PortInterface</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst eine lineare Generalisierungshierarchie:</p>\n<ul class=\"fig-list\"><li><code>PortInterface</code>: Basismetasklasse ohne gesondert dargestellte Stereotypen.\n</li><li><code>PlatformHealthManagementInterface</code>: Abstrakte Spezialisierung von <code>PortInterface</code>.\n</li><li><code>PhmAbstractRecoveryNotificationInterface</code>: Abstrakte Spezialisierung von <code>PlatformHealthManagementInterface</code>.\n</li><li><code>PhmSupervisionRecoveryNotificationInterface</code>: Konkrete Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Verhaltens- oder Sequenzdiagramm-Elemente. Die Beziehungen repräsentieren Generalisierungen/Spezialisierungen (<code>is-a</code>) zur typisierten Benachrichtigung von Wiederherstellungsaktionen im PHM-Kontext.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Festlegung der Metamodellstruktur für Benachrichtigungsschnittstellen im PHM. Für Recovery-Benachrichtigungen steht im gezeigten Metamodell als Spezialisierung von <code>PhmAbstractRecoveryNotificationInterface</code> die Schnittstelle <code>PhmSupervisionRecoveryNotificationInterface</code> zur Verfügung. Validierungswerkzeuge und Codegeneratoren müssen Manifeste auf diese Schnittstellenhierarchie abstimmen.</p>"}], "trans": [{"from": "FIG-349057b0dcc4fdf2", "to": "FIG-61f470539b21a6d1", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-61f470539b21a6d1", "to": "FIG-23b47d9b1e98cc46", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Diagrammlayout: Verkleinerung und Re-Arrangieren der Klassenkästen (<code>PortInterface</code> in der Breite reduziert) ohne inhaltliche Modelländerungen.\n</li></ul>"}, {"from": "FIG-23b47d9b1e98cc46", "to": "FIG-97e305141de0f277", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-97e305141de0f277", "to": "FIG-e1886a37b828dc9f", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Metaklasse <code>PhmHealthChannelRecoveryNotificationInterface</code>: Entfall der Spezialisierungsklasse von <code>PhmAbstractRecoveryNotificationInterface</code>.\n</li><li>Metaklasse <code>PortInterface</code>: Entfall der Stereotype bzw. Mixin-/Kind-Beziehungen <code>«ARElement»</code>, <code>«AtpBlueprint»</code>, <code>«AtpBlueprintable»</code> und <code>«AtpType»</code> in der Klassendarstellung.\n</li></ul>"}, {"from": "FIG-e1886a37b828dc9f", "to": "FIG-ab21472678ff724e", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
